INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04089','Mesh','Component made of overlapping strands forming a fine net-like structure.','C71222',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04090','Motor(s)','A machine that converts any form of energy to produce or impart motion (kinetic energy).','C50077',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04091','Mount','A structural component designed to facilitate the attachment of one object to another.','C50079',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04092','Needle','A component with a long, slender, pointed shape.','C50290',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04093','Nozzle','A component designed to regulate and direct the flow of a fluid or gas.','C50291',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04094','Packaging','The outer wrapping around a device which serves to contain, identify, and protect it prior to use.','C185295',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04095','Pad','Typically a soft, cushion-like material used to prevent injury or damage to a person or device. Can also be made of an absorbent material to absorb liquid.','C50095',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04096','Panel','A rigid sheet that forms a surface of a device or component.','C50096',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04097','Plate','A thin, flat sheet or strip used to join, strengthen or to form parts of another structure. For a flat, shallow container with a raised rim, use G03016.','C50106',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04098','Plug','A component designed to seat into an opening in a device or other object.','C50108',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04099','Plunger','A component of a machine, tool or device that pushes or thrusts another object, liquid or gas.','C50297',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04100','Post','An upright piece that is fixed firmly that supports, place or aligns other parts.','C50112',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04101','Potting','The resin, glue or other substance used to seal other components together.','C172798',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04102','Probe','A component designed to reach into a location for manipulating or for measuring.','C50121',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04103','Processor','A component designed for preparing or treating a material. Should not be used for computer processors.','C50122',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04104','Pulley','A component which changes the direction of a force (e.g. belt or chain).','C50126',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04105','Pump','A component designed to facilitate the movement of a fluid.','C50128',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04106','Pusher','A component designed to advance something by pushing it.','C54023',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04107','Rachet','A part that allows or forces another part''s movement in a single direction.','C172799',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04108','Rail','A bar designed for support, attachment, guidance, or protection from falling.','C50130',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0410801','Side Rail','A supportive or protective rail attached to the side of something.','C50301','G04108','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04109','Regulator','A component designed to control a process or condition.','C50137',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04110','Reservoir','A vessel designed to store a fluid.','C50140',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04111','Ring','A circular band-shaped component.','C50148',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04112','Rod/Shaft','A long cylindrical bar used to transmit motion or connect other components.','C50153',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04113','Seal','A component designed to prevent passage of material through a joint or opening.','C50163',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04114','Shock Absorber','A mechanical component designed to dampen or attenuate a force.','C172139',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
