INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04116','Slide','A flat rectangular piece of glass on which specimens can be mounted for microscopic study.','C50178',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
