INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04118','Spacer','A component designed to position objects further apart.','C50182',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04119','Spring','An elastic component designed to bend under a load and then return to its shape when unloaded.','C50187',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04120','Stand','A support component designed to hold an object.','C50189',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04121','Steering Wire','A wire designed to enable a device to be maneuvered.','C50337',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04122','Stent','Tubular support placed inside a blood vessel, canal, or duct to aid healing or relieve an obstruction.','C50190',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
