INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04135','Valve(s)','A mechanical component designed to control the flow of a fluid or gas.','C50243',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
