INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0413502','Luer Valve','A valve that incorporates a Luer fitting.','C50260','G04135','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0413503','One-Way Valve','A valve designed to allow flow in only one direction.','C50334','G04135','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0413504','Control Clamp','A clamp mechanism designed to occlude flow within a medical device system. This includes roller clamps, slide clamps, and pinch clamps.','C227072','G04135','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04136','Vaporiser','A component for gasifying liquids such as drugs.','C50262',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04137','Vibrator','A mechanical component designed to create a vibratory motion.','C50265',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04138','Washer','A flattened disk used as a mechanical seal between objects.','C50267',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G04139','Weld','Any joining connection that is the result of welding 2 or more parts.','C89532',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
