INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05001','Camera','An apparatus for taking photographs, generally consisting of a lightproof enclosure having an aperture with a shuttered lens through which the image of an object is focused and recorded.','C49858',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05002','Film','A photographic material designed to capture an image upon exposure to electromagnetic radiation.','C49955',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05003','Imager','A component designed to create or record a visual representation.','C49997',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
