INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05005','LED (Light Emitting Diode)','A type of diode designed to emit light when a current passes through it.','C49923',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05006','Lenses','An electric or optical component designed to focus (concentrate) or disperse electromagnetic radiation.','C50030',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05007','Light Source','A component that produces visible light.','C172002',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0500701','Bulb','A component designed to produce light or heat.','C171946','G05007','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05008','Mirror','A component consisting of a polished surface designed to reflect light.','C50070',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G05009','Optical Fiber','A component made with thin glass fibers as a conduit for transmission of light.','C49954',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06001','Alarm','A component designed to signal the occurrence of a particular event.','C49813',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0600101','Alarm, Audible','A component designed to signal the occurrence of a particular event by making a sound.','C49814','G06001','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0600102','Alarm, Visual','A component designed to signal the occurrence of a particular event in a way that can be seen.','C49822','G06001','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06002','Emergency Button Or Switch','A button and circuits designed to force the shutdown of a machine or device.','C50308',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06003','Fail-Safe System','A component designed to prevent malfunction, unsafe, or unauthorized operation of a device or system.','C50208',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06004','Locking Mechanism','A fastening component designed to hold, close, or secure.','C50286',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06005','Protector/Shield','A component designed to prevent harm or protect against damage to other components.','C50171',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06006','Safety Interlock','A mechanical or electronic component designed to prevent undesired actions due to the changing state of a device, typically to prevent harm to an operator or damage to the device itself.','C50154',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G0600601','Needle Stick Prevention Mechanism','A mechanism integrated into a device to prevent needle stick injuries.','C172013','G06006','FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G06007','Safety Valve','A valve designed to automatically open in order to maintain the pressure in a system below a specified pressure.','C50257',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G07001','Part/Component/Sub-assembly Term not Applicable','The device does not have distinct parts, components, or sub-assemblies, or it would not be appropriate to link the reported incident to a single part, component, or sub-assembly. Use this term if the problem involves or affects the overall device rather than a specific component.','C172015',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G07002','Appropriate Component Term/Code Not Available','The parts, components, or sub-assemblies are not adequately described by any other term. Note: this code must not be used unless there is no other feasible code. The preferred term should be documented when submitting an adverse event report. This information will be used to determine if a new term should be added to the code table.','C171943',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
INSERT INTO component_library(code,name,definition,ncit_code,parent_code,source) VALUES ('G07003','Insufficient Component Information','There is not enough information available to classify the medical device component or there is not enough information available to determine whether a medical device component is affected.','C187378',NULL,'FDA CDRH NCIt Subsets 26.08e - Medical Device Component');
