-- V6: biblioteca de componentes (vocabulario controlado).
-- Fuente: FDA CDRH / NCIt Subsets, version 26.08e, subconjunto "Medical Device Component"
-- (codigos IMDRF Anexo G). 299 terminos. El codigo IMDRF es el ID estable; el nombre es el
-- "CDRH Preferred Term". parent_code solo existe cuando el codigo de 8 caracteres tiene su
-- codigo de 6 caracteres presente en la misma lista (74 de 74).
CREATE TABLE component_library (
    code         TEXT PRIMARY KEY,                       -- p. ej. G02012 (IMDRF sin prefijo)
    name         TEXT NOT NULL CHECK (length(trim(name)) > 0),
    definition   TEXT,
    ncit_code    TEXT,
    parent_code  TEXT REFERENCES component_library(code),
    source       TEXT NOT NULL CHECK (length(trim(source)) > 0)
);
CREATE UNIQUE INDEX ux_component_library_name ON component_library(lower(name));
CREATE INDEX ix_component_library_parent ON component_library(parent_code);

